  1	package com.pousada;
  2	
  3	import com.pousada.api.ApiRoutes;
  4	import com.pousada.database.Database;
  5	import io.javalin.Javalin;
  6	
  7	public class Application {
  8	    public static void main(String[] args) {
  9	        String dbUrl = System.getenv("DB_URL");
 10	        String dbUser = System.getenv("DB_USER");
 11	        String dbPassword = System.getenv("DB_PASSWORD");
 12	        String portStr = System.getenv("PORT");
 13	
 14	        if (dbUrl == null || dbUser == null || dbPassword == null) {
 15	            System.err.println("Missing required environment variables: DB_URL, DB_USER, DB_PASSWORD");
 16	            System.exit(1);
 17	        }
 18	
 19	        int port = portStr != null ? Integer.parseInt(portStr) : 7070;
 20	
 21	        Database database = new Database(dbUrl, dbUser, dbPassword);
 22	        ApiRoutes apiRoutes = new ApiRoutes(database);
 23	
 24	        Javalin app = Javalin.create()
 25	            .start(port);
 26	
 27	        apiRoutes.register(app);
 28	
 29	        System.out.println("Pousada Maré Alta server started on port " + port);
 30	
 31	        Runtime.getRuntime().addShutdownHook(new Thread(() -> {
 32	            app.stop();
 33	            database.close();
 34	        }));
 35	    }
 36	}
 37	package com.pousada.api;
 38	
 39	import com.fasterxml.jackson.databind.ObjectMapper;
 40	import com.pousada.database.Database;
 41	import com.pousada.database.MessageRepository;
 42	import com.pousada.database.ReservationRepository;
 43	import com.pousada.database.RoomRepository;
 44	import com.pousada.exception.ApiException;
 45	import com.pousada.model.Reservation;
 46	import com.pousada.model.ReservationStatus;
 47	import com.pousada.model.RatePlan;
 48	import com.pousada.model.Room;
 49	import com.pousada.service.ReportService;
 50	import com.pousada.service.ReservationService;
 51	import com.pousada.util.Formatter;
 52	import io.javalin.Javalin;
 53	import io.javalin.http.Context;
 54	import java.math.BigDecimal;
 55	import java.sql.SQLException;
 56	import java.time.LocalDate;
 57	import java.time.YearMonth;
 58	import java.time.format.DateTimeFormatter;
 59	import java.util.HashMap;
 60	import java.util.List;
 61	import java.util.Map;
 62	import java.util.stream.Collectors;
 63	
 64	public class ApiRoutes {
 65	    private final Database database;
 66	    private final RoomRepository roomRepository;
 67	    private final ReservationRepository reservationRepository;
 68	    private final MessageRepository messageRepository;
 69	    private final ReservationService reservationService;
 70	    private final ReportService reportService;
 71	    private final ObjectMapper objectMapper = new ObjectMapper();
 72	
 73	    public ApiRoutes(Database database) {
 74	        this.database = database;
 75	        this.roomRepository = new RoomRepository(database);
 76	        this.reservationRepository = new ReservationRepository(database);
 77	        this.messageRepository = new MessageRepository(database);
 78	        this.reservationService = new ReservationService(roomRepository, reservationRepository, messageRepository);
 79	        this.reportService = new ReportService(roomRepository, reservationRepository);
 80	    }
 81	
 82	    public void register(Javalin app) {
 83	        app.get("/rooms", this::getRooms);
 84	        app.post("/reservations", this::createReservation);
 85	        app.get("/reservations/{id}", this::getReservation);
 86	        app.post("/reservations/{id}/confirmation", this::confirmReservation);
 87	        app.post("/reservations/{id}/cancellation", this::cancelReservation);
 88	        app.post("/reservations/{id}/check-in", this::checkIn);
 89	        app.post("/reservations/{id}/check-out", this::checkOut);
 90	        app.get("/reservations/{id}/document", this::getDocument);
 91	        app.get("/messages", this::getMessages);
 92	        app.get("/reports/occupancy", this::getOccupancyReport);
 93	        app.get("/reports/revenue", this::getRevenueReport);
 94	    }
 95	
 96	    private void getRooms(Context ctx) throws SQLException {
 97	        List<Room> rooms = roomRepository.findAll();
 98	        List<Map<String, Object>> response = rooms.stream().map(room -> {
 99	            Map<String, Object> map = new HashMap<>();
100	            map.put("number", room.getNumber());
101	            map.put("type", room.getType().getDisplayName());
102	            map.put("capacity", room.getCapacity());
103	            map.put("nightlyRate", room.getNightlyRate());
104	            return map;
105	        }).collect(Collectors.toList());
106	        ctx.json(response);
107	    }
108	
109	    private void createReservation(Context ctx) {
110	        try {
111	            Map<String, Object> body = ctx.bodyAsClass(Map.class);
112	
113	            Object roomNumberObj = body.get("roomNumber");
114	            Object guestNameObj = body.get("guestName");
115	            Object guestEmailObj = body.get("guestEmail");
116	            Object guestCpfObj = body.get("guestCpf");
117	            Object checkInObj = body.get("checkIn");
118	            Object checkOutObj = body.get("checkOut");
119	            Object guestsObj = body.get("guests");
120	            Object ratePlanObj = body.get("ratePlan");
121	            Object companyCodeObj = body.get("companyCode");
122	
123	            if (roomNumberObj == null || guestNameObj == null || guestEmailObj == null ||
124	                guestCpfObj == null || checkInObj == null || checkOutObj == null ||
125	                guestsObj == null || ratePlanObj == null) {
126	                errorResponse(ctx, 400, "INVALID_REQUEST", "Missing required fields");
127	                return;
128	            }
129	
130	            int roomNumber = ((Number) roomNumberObj).intValue();
131	            String guestName = guestNameObj.toString();
132	            String guestEmail = guestEmailObj.toString();
133	            String guestCpf = guestCpfObj.toString();
134	            LocalDate checkIn = LocalDate.parse(checkInObj.toString(), DateTimeFormatter.ISO_DATE);
135	            LocalDate checkOut = LocalDate.parse(checkOutObj.toString(), DateTimeFormatter.ISO_DATE);
136	            int guests = ((Number) guestsObj).intValue();
137	            RatePlan ratePlan = RatePlan.valueOf(ratePlanObj.toString().toUpperCase());
138	            String companyCode = companyCodeObj != null ? companyCodeObj.toString() : null;
139	
140	            Reservation reservation = reservationService.createReservation(
141	                roomNumber, guestName, guestEmail, guestCpf, checkIn, checkOut, guests, ratePlan, companyCode);
142	
143	            ctx.status(201);
144	            ctx.json(reservationToJson(reservation));
145	        } catch (Exception e) {
146	            handleException(ctx, e);
147	        }
148	    }
149	
150	    private void getReservation(Context ctx) {
151	        try {
152	            long id = ctx.pathParamAsClass("id", Long.class).get();
153	            Reservation reservation = reservationRepository.findById(id)
154	                .orElseThrow(() -> new IllegalArgumentException("RESERVATION_NOT_FOUND"));
155	            ctx.json(reservationToJson(reservation));
156	        } catch (Exception e) {
157	            handleException(ctx, e);
158	        }
159	    }
160	
161	    private void confirmReservation(Context ctx) {
162	        try {
163	            long id = ctx.pathParamAsClass("id", Long.class).get();
164	            Map<String, Object> body = ctx.bodyAsClass(Map.class);
165	
166	            Reservation reservation = reservationService.confirmReservation(
167	                id, new BigDecimal(body.get("amountPaid").toString()));
168	            ctx.json(reservationToJson(reservation));
169	        } catch (Exception e) {
170	            handleException(ctx, e);
171	        }
172	    }
173	
174	    private void cancelReservation(Context ctx) {
175	        try {
176	            long id = ctx.pathParamAsClass("id", Long.class).get();
177	            Reservation reservation = reservationService.cancelReservation(id);
178	            ctx.json(reservationToJson(reservation));
179	        } catch (Exception e) {
180	            handleException(ctx, e);
181	        }
182	    }
183	
184	    private void checkIn(Context ctx) {
185	        try {
186	            long id = ctx.pathParamAsClass("id", Long.class).get();
187	            Reservation reservation = reservationService.checkIn(id);
188	            ctx.json(reservationToJson(reservation));
189	        } catch (Exception e) {
190	            handleException(ctx, e);
191	        }
192	    }
193	
194	    private void checkOut(Context ctx) {
195	        try {
196	            long id = ctx.pathParamAsClass("id", Long.class).get();
197	            Reservation reservation = reservationService.checkOut(id);
198	            Room room = roomRepository.findByNumber(reservation.getRoomNumber()).orElseThrow();
199	            ctx.json(formatReceipt(reservation, room));
200	        } catch (Exception e) {
201	            handleException(ctx, e);
202	        }
203	    }
204	
205	    private void getDocument(Context ctx) {
206	        try {
207	            long id = ctx.pathParamAsClass("id", Long.class).get();
208	            Reservation reservation = reservationRepository.findById(id)
209	                .orElseThrow(() -> new IllegalArgumentException("RESERVATION_NOT_FOUND"));
210	
211	            if (reservation.getStatus() != ReservationStatus.CONFIRMED &&
212	                reservation.getStatus() != ReservationStatus.CHECKED_IN &&
213	                reservation.getStatus() != ReservationStatus.CHECKED_OUT) {
214	                errorResponse(ctx, 409, "OPERATION_NOT_ALLOWED", "Document not available for this reservation");
215	                return;
216	            }
217	
218	            Room room = roomRepository.findByNumber(reservation.getRoomNumber()).orElseThrow();
219	            ctx.json(formatReceipt(reservation, room));
220	        } catch (Exception e) {
221	            handleException(ctx, e);
222	        }
223	    }
224	
225	    private void getMessages(Context ctx) {
226	        try {
227	            var messages = messageRepository.findAll();
228	            var response = messages.stream().map(msg -> {
229	                Map<String, Object> map = new HashMap<>();
230	                map.put("id", msg.getId());
231	                map.put("channel", msg.getChannel());
232	                map.put("to", msg.getTo());
233	                map.put("subject", msg.getSubject());
234	                map.put("body", msg.getBody());
235	                return map;
236	            }).collect(Collectors.toList());
237	            ctx.json(response);
238	        } catch (Exception e) {
239	            handleException(ctx, e);
240	        }
241	    }
242	
243	    private void getOccupancyReport(Context ctx) {
244	        try {
245	            String dateStr = ctx.queryParam("date");
246	            if (dateStr == null) {
247	                errorResponse(ctx, 400, "INVALID_REQUEST", "Missing date parameter");
248	                return;
249	            }
250	
251	            LocalDate date = LocalDate.parse(dateStr, DateTimeFormatter.ISO_DATE);
252	            try (var conn = database.getConnection()) {
253	                String report = reportService.generateOccupancyReport(date, conn);
254	                ctx.header("Content-Type", "text/csv;charset=utf-8");
255	                ctx.result(report);
256	            }
257	        } catch (Exception e) {
258	            handleException(ctx, e);
259	        }
260	    }
261	
262	    private void getRevenueReport(Context ctx) {
263	        try {
264	            String monthStr = ctx.queryParam("month");
265	            if (monthStr == null) {
266	                errorResponse(ctx, 400, "INVALID_REQUEST", "Missing month parameter");
267	                return;
268	            }
269	
270	            YearMonth month = YearMonth.parse(monthStr, DateTimeFormatter.ofPattern("yyyy-MM"));
271	            try (var conn = database.getConnection()) {
272	                String report = reportService.generateRevenueReport(month, conn);
273	                ctx.header("Content-Type", "text/csv;charset=utf-8");
274	                ctx.result(report);
275	            }
276	        } catch (Exception e) {
277	            handleException(ctx, e);
278	        }
279	    }
280	
281	    private Map<String, Object> reservationToJson(Reservation reservation) {
282	        Map<String, Object> map = new HashMap<>();
283	        map.put("id", reservation.getId());
284	        map.put("roomNumber", reservation.getRoomNumber());
285	        map.put("guestName", reservation.getGuestName());
286	        map.put("guestEmail", reservation.getGuestEmail());
287	        map.put("guestCpf", reservation.getGuestCpf());
288	        map.put("checkIn", Formatter.formatDateIso(reservation.getCheckIn()));
289	        map.put("checkOut", Formatter.formatDateIso(reservation.getCheckOut()));
290	        map.put("guests", reservation.getGuests());
291	        map.put("ratePlan", reservation.getRatePlan());
292	        map.put("nights", reservation.getNights());
293	        map.put("subtotal", reservation.getSubtotal());
294	        map.put("discount", reservation.getDiscount());
295	        map.put("total", reservation.getTotal());
296	        map.put("status", reservation.getStatus());
297	        map.put("amountPaid", reservation.getAmountPaid());
298	        map.put("refund", reservation.getRefund());
299	        return map;
300	    }
301	
302	    private Map<String, Object> formatReceipt(Reservation reservation, Room room) {
303	        Map<String, Object> map = new HashMap<>();
304	        map.put("title", "Comprovante de reserva");
305	        map.put("reservationId", reservation.getId());
306	        map.put("guestName", reservation.getGuestName());
307	        map.put("guestCpf", reservation.getGuestCpf());
308	        map.put("roomNumber", reservation.getRoomNumber());
309	        map.put("roomType", room.getType().getDisplayName());
310	        map.put("checkIn", Formatter.formatDateIso(reservation.getCheckIn()));
311	        map.put("checkOut", Formatter.formatDateIso(reservation.getCheckOut()));
312	        map.put("nights", reservation.getNights());
313	        map.put("subtotal", reservation.getSubtotal());
314	        map.put("discount", reservation.getDiscount());
315	        map.put("total", reservation.getTotal());
316	        return map;
317	    }
318	
319	    private void handleException(Context ctx, Exception e) {
320	        if (e instanceof ApiException apiEx) {
321	            errorResponse(ctx, apiEx.getStatusCode(), apiEx.getErrorCode(), apiEx.getMessage());
322	        } else {
323	            errorResponse(ctx, 500, "INTERNAL_ERROR", "An error occurred");
324	        }
325	    }
326	
327	    private void errorResponse(Context ctx, int status, String code, String message) {
328	        ctx.status(status);
329	        Map<String, Object> error = new HashMap<>();
330	        error.put("error", code);
331	        error.put("message", message);
332	        ctx.json(error);
333	    }
334	}

