171	        sb.append("Hóspede: ").append(reservation.getGuestName())
172	          .append(" (CPF ").append(Formatter.formatCpf(reservation.getGuestCpf())).append(")\n");
173	        sb.append("Quarto: ").append(reservation.getRoomNumber())
174	          .append(" (").append(room.getType().getDisplayName()).append(")\n");
