215	    public String generateOccupancyReport(LocalDate date, Connection conn) throws SQLException {
216	        List<Room> allRooms = roomRepository.findAll();
217	
218	        StringBuilder csv = new StringBuilder();
219	        csv.append("room,type,reservation,check_in,check_out\n");
220	
221	        int occupiedCount = 0;
222	
223	        try (var stmt = conn.prepareStatement(
224	            "SELECT id, room_number, check_in, check_out FROM reservations " +
225	            "WHERE status != ? AND check_in <= ? AND check_out > ? " +
226	            "ORDER BY room_number")) {
227	
228	            stmt.setString(1, ReservationStatus.CANCELLED.toString());
229	            stmt.setDate(2, Date.valueOf(date));
230	            stmt.setDate(3, Date.valueOf(date));
231	
232	            ResultSet rs = stmt.executeQuery();
233	            var rows = new ArrayList<OccupancyRow>();
234	            while (rs.next()) {
235	                rows.add(new OccupancyRow(
236	                    rs.getLong("id"),
237	                    rs.getInt("room_number"),
238	                    rs.getDate("check_in").toLocalDate(),
239	                    rs.getDate("check_out").toLocalDate()
240	                ));
241	            }
242	
243	            for (var row : rows) {
244	                Room room = allRooms.stream()
245	                    .filter(r -> r.getNumber() == row.roomNumber)
246	                    .findFirst()
247	                    .orElse(null);
248	
249	                if (room != null) {
250	                    csv.append(row.roomNumber).append(",")
251	                       .append(room.getType().getDisplayName()).append(",")
252	                       .append(row.reservationId).append(",")
253	                       .append(Formatter.formatDateIso(row.checkIn)).append(",")
254	                       .append(Formatter.formatDateIso(row.checkOut)).append("\n");
255	                    occupiedCount++;
256	                }
257	            }
258	        }
259	
260	        csv.append("total,").append(occupiedCount).append("/").append(allRooms.size());
261	
262	        return csv.toString();
263	    }
264	
265	    public String generateRevenueReport(YearMonth yearMonth, Connection conn) throws SQLException {
266	        StringBuilder csv = new StringBuilder();
267	        csv.append("reservation,room,check_in,check_out,status,amount\n");
268	
269	        BigDecimal total = BigDecimal.ZERO;
270	
271	        try (var stmt = conn.prepareStatement(
272	            "SELECT id, room_number, check_in, check_out, status, amount_paid, refund " +
273	            "FROM reservations " +
274	            "WHERE EXTRACT(YEAR FROM check_in) = ? AND EXTRACT(MONTH FROM check_in) = ? " +
275	            "AND (status IN (?, ?, ?) OR (status = ? AND amount_paid > 0)) " +
276	            "ORDER BY check_in, id")) {
277	
278	            stmt.setInt(1, yearMonth.getYear());
279	            stmt.setInt(2, yearMonth.getMonthValue());
280	            stmt.setString(3, ReservationStatus.CONFIRMED.toString());
281	            stmt.setString(4, ReservationStatus.CHECKED_IN.toString());
282	            stmt.setString(5, ReservationStatus.CHECKED_OUT.toString());
283	            stmt.setString(6, ReservationStatus.CANCELLED.toString());
284	
285	            ResultSet rs = stmt.executeQuery();
286	            var rows = new ArrayList<RevenueRow>();
287	            while (rs.next()) {
288	                rows.add(new RevenueRow(
289	                    rs.getLong("id"),
290	                    rs.getInt("room_number"),
291	                    rs.getDate("check_in").toLocalDate(),
292	                    rs.getDate("check_out").toLocalDate(),
293	                    rs.getString("status"),
294	                    rs.getBigDecimal("amount_paid"),
295	                    rs.getBigDecimal("refund")
296	                ));
297	            }
298	
299	            for (var row : rows) {
300	                BigDecimal amount = row.amountPaid;
301	                if (row.refund != null && row.refund.compareTo(BigDecimal.ZERO) > 0) {
302	                    amount = row.amountPaid.subtract(row.refund);
303	                }
304	
305	                csv.append(row.reservationId).append(",")
306	                   .append(row.roomNumber).append(",")
307	                   .append(Formatter.formatDateIso(row.checkIn)).append(",")
308	                   .append(Formatter.formatDateIso(row.checkOut)).append(",")
309	                   .append(row.status).append(",")
310	                   .append(Formatter.formatCurrencyForCsv(amount)).append("\n");
311	
312	                total = total.add(amount);
313	            }
314	        }
315	
316	        csv.append("total,,,,").append(Formatter.formatCurrencyForCsv(total));
317	
318	        return csv.toString();
319	    }
320	
321	    private record OccupancyRow(long reservationId, int roomNumber, LocalDate checkIn, LocalDate checkOut) {}
322	    private record RevenueRow(long reservationId, int roomNumber, LocalDate checkIn, LocalDate checkOut,
323	                             String status, BigDecimal amountPaid, BigDecimal refund) {}
324	}

