    22	    @Override
    23	    public PricingResult calculatePrice(Room room, LocalDate checkIn, LocalDate checkOut, int nights) {
    24	        BigDecimal subtotal = BigDecimal.ZERO;
    25	
    26	        for (int i = 0; i < nights; i++) {
    27	            LocalDate night = checkIn.plusDays(i);
    28	            BigDecimal nightPrice = PriceCalculator.applySeasonalAdjustment(room.getNightlyRate(), night);
    29	            nightPrice = PriceCalculator.roundPrice(nightPrice);
    30	            subtotal = subtotal.add(nightPrice);
