     1	package com.pousada.util;
     2	
     3	import java.math.BigDecimal;
     4	import java.math.RoundingMode;
     5	import java.time.LocalDate;
     6	
     7	public class PriceCalculator {
     8	    private static final RoundingMode ROUNDING = RoundingMode.HALF_EVEN;
     9	
    10	    public static boolean isHighSeason(LocalDate date) {
    11	        int month = date.getMonthValue();
    12	        int day = date.getDayOfMonth();
    13	
    14	        if (month == 7) {
    15	            return true;
    16	        }
    17	
    18	        if (month == 12) {
    19	            return day >= 15;
    20	        }
    21	
    22	        if (month <= 2) {
    23	            return true;
    24	        }
    25	
    26	        return false;
    27	    }
    28	
    29	    public static BigDecimal roundPrice(BigDecimal value) {
    30	        return value.setScale(2, ROUNDING);
    31	    }
    32	
    33	    public static BigDecimal applySeasonalAdjustment(BigDecimal nightlyRate, LocalDate date) {
    34	        if (isHighSeason(date)) {
    35	            return roundPrice(nightlyRate.multiply(BigDecimal.valueOf(1.20)));
    36	        }
    37	        return nightlyRate;
    38	    }
    39	
    40	    public static int calculateNights(LocalDate checkIn, LocalDate checkOut) {
    41	        return (int) java.time.temporal.ChronoUnit.DAYS.between(checkIn, checkOut);
    42	    }
    43	
    44	    public static boolean isWeekend(LocalDate date) {
    45	        int dayOfWeek = date.getDayOfWeek().getValue();
    46	        return dayOfWeek == 5 || dayOfWeek == 6 || dayOfWeek == 7;
    47	    }
    48	
    49	    public static boolean isWeekendPackageValid(LocalDate checkIn, LocalDate checkOut) {
    50	        int days = calculateNights(checkIn, checkOut);
    51	        if (days != 2) {
    52	            return false;
    53	        }
    54	
    55	        int checkInDow = checkIn.getDayOfWeek().getValue();
    56	        int checkOutDow = checkOut.getDayOfWeek().getValue();
    57	
    58	        return checkInDow == 5 && checkOutDow == 7;
    59	    }
    60	}

